int setsockopt_pppox_l2tp(struct socket *sock, int level, int optname,
                          char __user *optval, unsigned int optlen)
{
    struct sock *sk = sock->sk;
    struct pppox_sock *po = pppox_sk(sk);
    struct pppol2tp_session *session;
    int err;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(int))
        return -EINVAL;

    if (sk->sk_state != PPPOX_CONNECTED)
        return -ENOTCONN;

    session = pppol2tp_get_session_by_sock(sock);
    if (!session)
        return -ENOENT;

    switch (optname) {
    case PPPOL2TP_SO_IFNAME:
        if (optlen < sizeof(char *)) {
            err = -EINVAL;
            break;
        }
        if (copy_from_user(&session->ifname, optval, sizeof(char *))) {
            err = -EFAULT;
            break;
        }
        break;
    case PPPOL2TP_SO_RECVSEQ:
        {
            int val;
            if (copy_from_user(&val, optval, sizeof(val))) {
                err = -EFAULT;
                break;
            }
            session->recv_seq = val ? 1 : 0;
        }
        break;
    case PPPOL2TP_SO_SENDSEQ:
        {
            int val;
            if (copy_from_user(&val, optval, sizeof(val))) {
                err = -EFAULT;
                break;
            }
            session->send_seq = val ? 1 : 0;
        }
        break;
    case PPPOL2TP_SO_DEBUG:
        {
            int val;
            if (copy_from_user(&val, optval, sizeof(val))) {
                err = -EFAULT;
                break;
            }
            session->debug = val;
        }
        break;
    default:
        err = -ENOPROTOOPT;
        break;
    }

    if (session)
        pppol2tp_put_session(session);
    return err ? err : 0;
}

int setsockopt_pppol2tp(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    void *val;
    int err;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(int))
        return -EINVAL;

    val = kmalloc(optlen, GFP_KERNEL);
    if (!val)
        return -ENOMEM;

    err = copy_from_user(val, optval, optlen);
    if (err) {
        kfree(val);
        return -EFAULT;
    }

    if (!sock->sk->sk_state) {
        kfree(val);
        return -ENOTCONN;
    }

    session = pppol2tp_get_session(sk);
    if (!session) {
        kfree(val);
        return -ENOENT;
    }

    if (optname == PPCOL2TP_SO_SET_TLVS) {
        err = pppol2tp_set_tunnel_options(session, val, optlen);
    } else if (optname == PPCOL2TP_SO_SET_SESSION_OPTS) {
        err = pppol2tp_set_session_options(session, val, optlen);
    } else {
        err = -ENOPROTOOPT;
    }

    kfree(val);
    return err;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    struct sock *sk = sock->sk;
    struct pppol2tp_socket *po = pppol2tp_sk(sk);
    struct pppol2tp_session *session;
    int ret = 0;
    int val;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(int))
        return -EINVAL;

    if (copy_from_user(&val, optval, sizeof(val)))
        return -EFAULT;

    lock_sock(sk);

    if (!sock->sk->sk_state) {
        ret = -ENOTCONN;
        goto out;
    }

    session = pppol2tp_get_session(sk);
    if (!session) {
        ret = -ENOENT;
        goto out;
    }

    if (session->session_id) {
        if (val != 0)
            ret = pppol2tp_set_session_options(session, optname, val);
    } else {
        if (val != 0)
            ret = pppol2tp_set_tunnel_options(session->tunnel, optname, val);
    }

    pppol2tp_put_session(session);

out:
    release_sock(sk);
    return ret;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname, char __user *optval, unsigned int optlen) {
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int err = 0;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen < sizeof(int))
        return -EINVAL;

    if (sock->state == SS_UNCONNECTED)
        return -ECONNREFUSED;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOTCONN;

    switch (optname) {
        case PPPOL2TP_SO_IFNAME:
            if (optlen < sizeof(char) * IFNAMSIZ)
                return -EINVAL;
            if (copy_from_user(&session->ifname, optval, sizeof(char) * IFNAMSIZ))
                return -EFAULT;
            break;
        case PPPOL2TP_SO_SESSION_ID:
            {
                __be32 session_id;
                if (copy_from_user(&session_id, optval, sizeof(session_id)))
                    return -EFAULT;
                session->session_id = session_id;
                break;
            }
        case PPPOL2TP_SO_PEER_SESSION_ID:
            {
                __be32 peer_session_id;
                if (copy_from_user(&peer_session_id, optval, sizeof(peer_session_id)))
                    return -EFAULT;
                session->peer_session_id = peer_session_id;
                break;
            }
        default:
            return -ENOPROTOOPT;
    }

    return err;
}

int pppol2tp_setsockopt(struct socket *sock, int level, int optname,
                        char __user *optval, unsigned int optlen)
{
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int val;
    int err;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (optlen != sizeof(int))
        return -EINVAL;

    if (copy_from_user(&val, optval, sizeof(val)))
        return -EFAULT;

    if (!sk->sk_user_data)
        return -EBADFD;

    session = (struct pppol2tp_session *)sk->sk_user_data;

    switch (optname) {
    case PPPOL2TP_SO_RECVSEQ:
        session->recv_seq = val;
        break;
    case PPPOL2TP_SO_SENDSEQ:
        session->send_seq = val;
        break;
    case PPPOL2TP_SO_DEBUG:
        session->debug = val;
        break;
    default:
        return -ENOPROTOOPT;
    }

    return 0;
}
